<script setup>



import {uploadSelection} from '../../shared/uploadSelection.js'
import {computed, nextTick, onBeforeUnmount, onMounted, ref, watch} from 'vue'
import {onBeforeRouteLeave, onBeforeRouteUpdate, useRoute, useRouter} from 'vue-router'
import {api, post, stamp, operationId, openWorkspace} from '../api.js'
import {toast} from '../../shared/composables/toast.js'


import RichDescription from '../../deploy/components/RichDescription.vue'
import ActivityTimeline from '../components/ActivityTimeline.vue'
import CommentComposer from '../components/CommentComposer.vue'
import MarkdownEditor from '../../deploy/components/MarkdownEditor.vue'
import BugEvidence from '../components/BugEvidence.vue'
import WorkDeliveryRecords from '../components/WorkDeliveryRecords.vue'
import WorkChangeOverview from '../components/WorkChangeOverview.vue'
import WorkItemDocumentChanges from '../components/WorkItemDocumentChanges.vue'
import WorkDeliveryEditor from '../../deploy/components/WorkDeliveryEditor.vue'
import PageHeader from '../../shared/components/PageHeader.vue'
import SourceOperationReview from '../components/SourceOperationReview.vue'
import ResolveWorkItemDialog from '../components/ResolveWorkItemDialog.vue'
import ReleaseIntentFields from '../components/ReleaseIntentFields.vue'
import WorkDeliveryTracking from '../components/WorkDeliveryTracking.vue'
import WorkLoopPanel from '../components/WorkLoopPanel.vue'
const loopState=ref({dirty:false,busy:false})
import {safeWorkReturn} from '../navigation.js'
import {deliveryPreparation} from '../deliveryPreparation.js'
import HelpTip from '../../shared/components/HelpTip.vue'
import {fieldLabel, issueStatus, sourcePerson} from '../issueFields.js'
import {refreshActionConflict, conflictRefreshedMessage} from '../actionConflict.js'
const actionNotice=ref('')
const loadError=ref('')
const activityPeople=ref({}),assignees=ref([])
const personLabel=value=>sourcePerson(value,{...activityPeople.value,...(item.value?.person_labels||{}),...(remote.value?.users||{})})
const route=useRoute(),router=useRouter(),item=ref(null),remote=ref(null),activities=ref([]),sourceError=ref(''),tab=ref('overview'),busy=ref(false),uploading=ref(false),action=ref(''),options=ref(null),form=ref({}),comment=ref(''),commentAttachments=ref([]),operation=ref(null),pendingOperations=ref([]),services=ref([]),me=ref({}),editor=ref(null),baseline=ref(''),showDeliveryEditor=ref(false),editorState=ref({dirty:false,busy:false}),commentInput=ref(null),dictionaries=ref({}),starting=ref(false)
function sourceImage(address){try{const u=new URL(address),source=new URL(item.value.url);if(u.origin!==source.origin)return '';const id=u.searchParams.get('fileID')||/file-read-(\d+)\./.exec(u.pathname)?.[1];return id?new URL('api/research/work-items/'+item.value.id+'/images/'+id,location.href).href:''}catch{return ''}}
const fresh=computed(()=>route.params.id==='new'),external=computed(()=>item.value?.source?.startsWith('zentao:')),status=computed(()=>remote.value?.bug?.status||item.value?.external_status||item.value?.status),dirty=computed(()=>!!action.value&&JSON.stringify(form.value)!==baseline.value)
const releaseTrigger=ref(null)
const inlineAction=computed(()=>!!action.value&&action.value!=='release-intent')
const canManage=value=>me.value.role==='admin'||value?.owner===me.value.username
const descriptionTemplates={requirement:'## 背景与目标\n\n## 用户场景\n\n## 验收标准\n',bug:'## 环境与版本\n\n## 前置条件\n\n## 复现步骤\n1. \n\n## 预期结果\n\n## 实际结果\n'}
watch(()=>form.value.kind,(kind,previous)=>{if(action.value==='create'&&(!form.value.description||form.value.description===descriptionTemplates[previous]))form.value.description=descriptionTemplates[kind]||''})
const sourceIdentity=ref(''),canSourceWrite=computed(()=>!!remote.value&&sourceIdentity.value!=='public')
const followingBusy=ref(false),statusBusy=ref(false)
const canChangeStatus=computed(()=>!fresh.value&&!external.value&&(me.value.role==='admin'||item.value?.owner===me.value.username||item.value?.assigned_to===me.value.username))
async function updateStatus(status){if(statusBusy.value||busy.value||action.value||!item.value||status===item.value.status)return;statusBusy.value=true;try{const updated=await post('work-items/'+item.value.id+'/status',{status,expected_status:item.value.status,expected_updated_at:item.value.updated_at},'PATCH');item.value={...item.value,...updated};const data=await api('research/work-items/'+item.value.id);item.value=data.item;activities.value=data.activity||[];toast('状态已更新','success');if(window.parent!==window)window.parent.postMessage({type:'work-item.changed',id:item.value.id},location.origin)}catch(e){toast(e.message,'error');await load()}finally{statusBusy.value=false}}
async function toggleFollow(){if(followingBusy.value)return;followingBusy.value=true;try{const result=await post('research/work-items/'+item.value.id+'/follow',{following:!item.value.following},'PUT');item.value.following=result.following;toast(result.following?'已关注交付进展':'已取消关注','success')}catch(e){toast(e.message,'error')}finally{followingBusy.value=false}}
const resolving=ref(false),resolveOperation=ref(null),resolveState=ref({dirty:false,busy:false})
async function backToOrigin(){if(route.query.return==='home'&&window.parent!==window){if(loopState.value.dirty||dirty.value||commentDirty.value||editorState.value.dirty){await router.push(returnPath.value);return}window.parent.postMessage({type:'platform.home'},location.origin);return}await router.push(returnPath.value)}
const returnPath=computed(()=>safeWorkReturn(route.query.return_to,safeWorkReturn(router.options.history.state.back,route.query.return==='inbox'?'/':'/work')))
async function resolved(){resolving.value=false;resolveOperation.value=null;await load();if(window.parent!==window)window.parent.postMessage({type:'work-item.changed',id:item.value.id},location.origin)}
const commentDirty=computed(()=>!!comment.value.trim()||commentAttachments.value.length>0)
function warn(e){if(commentDirty.value||dirty.value||loopState.value.dirty||editor.value?.hasDraft()||resolveState.value.dirty){e.preventDefault();e.returnValue=''}}
function syncDirty(){if(window.parent!==window)window.parent.postMessage({type:'workspace.dirty',dirty:commentDirty.value||dirty.value||loopState.value.dirty||editorState.value.dirty||resolveState.value.dirty||false,busy:operationBusy.value||busy.value||uploading.value||loopState.value.busy||editorState.value.busy||resolveState.value.busy},location.origin)}
watch([dirty,commentDirty,busy,uploading],syncDirty)
const deliverySummary=ref(null),deliverySummaryLoading=ref(false),deliveryError=ref(''),records=ref([]),recordsError=ref(''),recordsLoading=ref(false),recordsMore=ref(false),recordsCursor=ref(0)
const preparation=computed(()=>deliveryPreparation(deliverySummary.value,{loading:deliverySummaryLoading.value,error:deliveryError.value}))
function openTesting(){openWorkspace('api-center','#/test-cases'+(item.value?.kind==='bug'?'?bug='+item.value.id:''))}
const detailTabs=computed(()=>[{id:'overview',name:'详情与活动'},{id:'changes-preview',name:'变更总览'+(deliverySummary.value?'（'+deliverySummary.value.changes.length+'）':'')},{id:'api-documents',name:'接口变更'},...(records.value.length?[{id:'delivery',name:'交付记录（'+records.value.length+(recordsMore.value?'+':'')+'）'}]:[])])
const deliveryOverview=computed(()=>{const names={code:'代码',mysql:'SQL',nacos:'配置',redis:'Redis',manual:'自定义记录',artifact:'制品','data-sync':'数据同步'},counts={};for(const c of deliverySummary.value?.changes||[])counts[c.kind]=(counts[c.kind]||0)+1;return Object.entries(counts).map(([k,n])=>(names[k]||k)+' '+n).join(' · ')||'暂无交付内容'})
async function loadDeliverySummary(){const id=route.params.id;if(id==='new')return;deliverySummaryLoading.value=true;deliverySummary.value=null;deliveryError.value='';try{const data=await api('work-items/'+id+'/delivery-content');if(String(route.params.id)!==String(id))return;if(!Array.isArray(data.changes))throw Error('交付内容响应无效');deliverySummary.value=data}catch(e){if(String(route.params.id)===String(id))deliveryError.value=e.message}finally{if(String(route.params.id)===String(id))deliverySummaryLoading.value=false}}
let recordRequest=0
async function loadRecords(more=false){const id=route.params.id;if(id==='new')return;const seq=++recordRequest;recordsLoading.value=true;try{const data=await api('research/work-items/'+id+'/delivery-records'+(more?'?before='+recordsCursor.value:''));if(seq!==recordRequest||String(route.params.id)!==String(id))return;if(!Array.isArray(data.items))throw Error('交付记录响应无效');records.value=more?[...records.value,...data.items]:data.items;recordsMore.value=!!data.has_more;recordsCursor.value=data.next_before||0;recordsError.value='';if(!records.value.length&&tab.value==='delivery')tab.value='overview'}catch(e){if(seq===recordRequest)recordsError.value=e.message}finally{if(seq===recordRequest)recordsLoading.value=false}}
const editorChangeID=ref(0)
async function openDeliveryEditor(changeID){if(busy.value||resolving.value)return;editorChangeID.value=Number.isSafeInteger(changeID)?changeID:0;showDeliveryEditor.value=true}
async function loadRelated(){await Promise.all([loadDeliverySummary(),loadRecords()])}
async function load(){if(fresh.value){item.value={source:'manual',kind:'requirement',title:'',description:descriptionTemplates.requirement,description_format:'markdown',assigned_to:me.value.username||'',status:'open',severity:'',priority:'3',resolution:'',release_required:true,metadata_revision:0};action.value='create';form.value={...item.value};baseline.value=JSON.stringify(form.value);return}busy.value=true;loadError.value='';try{const data=await api('research/work-items/'+route.params.id);item.value=data.item;remote.value=data.remote||null;sourceIdentity.value=data.source_identity||'';activities.value=data.activity||[];sourceError.value=data.source_error||'';pendingOperations.value=data.pending_operations||[]}catch(e){loadError.value=e.message;toast(e.message,'error')}finally{busy.value=false}}
async function openAction(name){if(operationBusy.value||busy.value)return;if(dirty.value&&!await confirmDiscard('放弃当前未保存内容并切换操作？'))return;if(name==='resolve'){action.value='';resolveOperation.value=null;resolving.value=true;return}action.value=name;operation.value=null;form.value={operation_id:operationId(),action:name,kind:item.value.kind,title:item.value.title,description:item.value.description,status:item.value.status||'open',severity:item.value.severity||'',priority:item.value.priority||'3',resolution:name==='resolve'?'fixed':item.value.resolution||'',comment:'',keep_following:name==='assignTo'?true:undefined,assigned_to:external.value?'':item.value.assigned_to||'',resolved_build:'',metadata:{release_required:null,no_release_reason:'',revision:item.value.metadata_revision}};options.value=null
 if(external.value&&name!=='release-intent'){busy.value=true;try{options.value=await api('research/work-items/'+item.value.id+'/action-options?action='+name);form.value.expected_digest=options.value.digest;form.value.title=options.value.bug?.title||form.value.title;form.value.description=options.value.bug?.steps??form.value.description;if(name==='resolve')form.value.resolution=options.value.resolutions?.fixed?'fixed':Object.keys(options.value.resolutions||{fixed:'已修复'})[0];form.value.assigned_to=options.value.assignedTo||options.value.bug?.assignedTo||'';form.value.resolved_build=options.value.bug?.resolvedBuild||'';if(form.value.assigned_to==='closed')form.value.assigned_to='';if(!form.value.resolved_build&&options.value.builds?.trunk)form.value.resolved_build='trunk'}catch(e){action.value='';toast(e.message,'error')}finally{busy.value=false}}
 baseline.value=JSON.stringify(form.value)
}
async function cancel(){if(busy.value||uploading.value)return;if(dirty.value&&!await confirmDiscard('放弃本次未保存内容？'))return;const creating=fresh.value;action.value='';operation.value=null;if(creating)await router.push(returnPath.value)}
watch(action,()=>{actionNotice.value=''})
async function refreshConflict(){
 try{const refreshed=await refreshActionConflict(item.value.id,form.value,api,data=>{item.value=data.item;remote.value=data.remote||null;sourceIdentity.value=data.source_identity||'';activities.value=data.activity||[];sourceError.value=data.source_error||'';pendingOperations.value=data.pending_operations||[]});options.value=refreshed.options;form.value=refreshed.form;actionNotice.value=conflictRefreshedMessage;toast(actionNotice.value,'warning',{duration:6000})}
 catch(e){actionNotice.value='刷新未完成，填写内容已保留。'+e.message;toast(actionNotice.value,'error',{duration:6000})}
}
async function submit(){if(operationBusy.value||busy.value||uploading.value)return;if(action.value==='release-intent'&&!form.value.metadata.use_rule&&(form.value.metadata.release_required==null||!form.value.metadata.no_release_reason.trim())){toast('请选择交付判定并填写人工调整原因，或恢复自动规则','warning');return}busy.value=true;try{
 if(external.value&&action.value!=='release-intent'&&!form.value.expected_digest){await refreshConflict();return}
 if(action.value==='release-intent'){await post('research/work-items/'+item.value.id+'/release-intent',form.value.metadata,'PUT');toast('已保存上线判定','success')}
 else if(external.value){const op=await post('research/work-items/'+item.value.id+'/actions',form.value);operation.value=op;if(op.state!=='success'){toast(op.message,'warning',{duration:6000});return};toast('已同步来源平台','success')}
 else if(action.value==='create'){const saved=await post('work-items',form.value);action.value='';baseline.value=JSON.stringify(form.value);busy.value=false;toast('工作项已创建','success');if(window.parent!==window)window.parent.postMessage({type:'work-item.changed',id:saved.id},location.origin);await router.replace({path:'/work/'+saved.id,query:{return_to:returnPath.value,...(route.query.return==='inbox'?{return:'inbox'}:{})}});return}
 else if(action.value==='edit'){await post('work-items/'+item.value.id,{...item.value,title:form.value.title,description:form.value.description,assigned_to:form.value.assigned_to,severity:form.value.severity,priority:form.value.priority,resolution:form.value.resolution},'PUT');toast('已保存','success')}

 clearSentComment(form.value);if(action.value==='release-intent'){await load();action.value=''}else{action.value='';await load()}if(window.parent!==window)window.parent.postMessage({type:'work-item.changed',id:item.value.id},location.origin)
 }catch(e){if(e.code==='research_source_conflict')await refreshConflict();else toast(e.message,'error',{duration:6000})}finally{busy.value=false}}
function clearSentComment(v){if(v?.action==='comment'&&comment.value===v.comment&&JSON.stringify(commentAttachments.value.map(a=>a.id))===JSON.stringify(v.attachments||[])){comment.value='';commentAttachments.value=[]}}
const operationBusy=ref(false)
function operationBusyChanged(value){operationBusy.value=value;syncDirty()}
async function inspectOperation(op){
 if(dirty.value&&!await confirmDiscard('放弃未保存内容并核对上次操作？'))return
 action.value='';operation.value=null;tab.value='overview'
 await nextTick();focusControl(document.querySelector('[data-source-operation="'+CSS.escape(op.id)+'"] button'))
}
async function operationVerified(op){
 clearSentComment(op.request)
 if(operation.value?.id===op.id){operation.value=null;action.value=''}
 await load()
 if(window.parent!==window)window.parent.postMessage({type:'work-item.changed',id:item.value.id},location.origin)
}
async function sendComment(){if((!comment.value.trim()&&!commentAttachments.value.length)||busy.value||uploading.value)return;
 if(external.value){await openAction('comment');if(action.value!=='comment'||!options.value)return;form.value.comment=comment.value;form.value.attachments=commentAttachments.value.map(a=>a.id);await submit();if(!action.value){comment.value='';commentAttachments.value=[]}}
 else{busy.value=true;try{await post('research/work-items/'+item.value.id+'/comment',{comment:comment.value,attachments:commentAttachments.value.map(a=>a.id)});comment.value='';commentAttachments.value=[];await load()}catch(e){toast(e.message,'error')}finally{busy.value=false}}
}
const chooseImages=uploadSelection(uploadFiles)
async function uploadFiles(files){if(uploading.value)return;uploading.value=true;try{for(const file of files){const body=new FormData();body.append('file',file);const result=await api('work-item-attachments',{method:'POST',body});form.value.attachments=[...(form.value.attachments||[]),result.id]}}catch(err){toast(err.message,'error')}finally{uploading.value=false}}
const resolutions=computed(()=>Object.entries(options.value?.resolutions||{fixed:'已修复',duplicate:'重复 Bug',notrepro:'无法重现',bydesign:'设计如此',external:'外部原因',postponed:'延期处理',willnotfix:'不予解决'}).map(([value,label])=>({value,label})))
const liveFields=computed(()=>({...item.value,severity:remote.value?.bug?.severity??item.value?.severity,priority:remote.value?.bug?.pri??item.value?.priority,resolution:remote.value?.bug?.resolution??item.value?.resolution,source_fields_read_at:remote.value?1:item.value?.source_fields_read_at,severity_label:remote.value?.bug?.severity!==undefined&&String(remote.value.bug.severity)!==item.value?.severity?'':item.value?.severity_label,priority_label:remote.value?.bug?.pri!==undefined&&String(remote.value.bug.pri)!==item.value?.priority?'':item.value?.priority_label,resolution_label:remote.value?.resolutions?.[remote.value?.bug?.resolution]|| (remote.value?.bug?.resolution!==undefined&&String(remote.value.bug.resolution)!==item.value?.resolution?'':item.value?.resolution_label)}))
watch(()=>[route.fullPath,item.value?.id,item.value?.kind,item.value?.title],()=>{if(item.value&&(fresh.value||String(item.value.id)===String(route.params.id))&&window.parent!==window)window.parent.postMessage({type:'workspace.label',label:(fresh.value?'新建工作项':(item.value.kind==='bug'?'Bug':'需求')+' #'+(item.value.external_id||item.value.id)+' · '+item.value.title)},location.origin)})
async function beginDelivery(){if(starting.value)return;starting.value=true;try{openWorkspace('deploy','#/orchestration?work_items='+item.value.id)}catch(e){toast(e.message,'error')}finally{starting.value=false}}
async function requestedAction(){if(route.query.operation){const op=pendingOperations.value.find(o=>o.id===route.query.operation);if(op){inspectOperation(op);return}}const requested=route.query.action;if(requested==='preview'){tab.value='changes-preview';return}if(requested==='changes'){await openDeliveryEditor();return}if(requested==='records'){if(records.value.length)tab.value='delivery';return}if(requested==='deliver'){await beginDelivery();return}if(requested==='comment'){tab.value='overview';await nextTick();focusControl(commentInput.value);return}if(['resolve','close','activate','assignTo','edit'].includes(requested)){if(external.value&&!canSourceWrite.value){toast('请验证本人来源账号后继续该操作','warning');return}await openAction(requested)}}
const builds=computed(()=>Object.entries(options.value?.builds||{}).map(([value,label])=>({value,label}))),users=computed(()=>Object.entries(options.value?.users||{}).filter(([value])=>value&&value!=='closed').map(([value,label])=>({value,label})))
const confirmingLeave=ref(false)
async function confirmDiscard(message){
 if(confirmingLeave.value)return false
 confirmingLeave.value=true
 try{await confirmDialog.confirm(message,'有未保存的内容',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑'});return true}catch{return false}finally{confirmingLeave.value=false}
}
async function canLeaveWork(){
 if(operationBusy.value||busy.value||statusBusy.value||uploading.value||loopState.value.busy||editorState.value.busy||resolveState.value.busy){toast('操作进行中，请等待结果','warning');return false}
 if(commentDirty.value||dirty.value||loopState.value.dirty||editor.value?.hasDraft()||resolveState.value.dirty)return confirmDiscard('当前有未保存内容，确认离开？')
 return true
}
onBeforeRouteLeave(canLeaveWork)
onBeforeRouteUpdate((to,from)=>to.params.id!==from.params.id||to.query.loop!==from.query.loop?canLeaveWork():true)
watch(()=>route.query.operation,async value=>{if(value&&String(item.value?.id)===String(route.params.id))await requestedAction()})
watch(()=>route.query.action,value=>{if(value==='preview'&&String(item.value?.id)===String(route.params.id))tab.value='changes-preview'})
watch(()=>route.params.id,async()=>{comment.value='';commentAttachments.value=[];action.value='';tab.value='overview';showDeliveryEditor.value=false;deliverySummary.value=null;records.value=[];recordsError.value='';deliveryError.value='';recordsMore.value=false;recordRequest++;editorState.value={dirty:false,busy:false};await Promise.all([loadRelated(),load()]);await requestedAction()})
onMounted(async()=>{window.addEventListener('beforeunload',warn);try{[me.value,services.value]=await Promise.all([api('/api/me'),api('services')]);const overview=await api('research/overview');dictionaries.value=Object.fromEntries((overview.connections||[]).map(c=>['zentao:'+c.name,c.field_labels||{}]));assignees.value=Object.entries(overview.assignees||{}).map(([value,label])=>({value,label:label===value?value:label+'（'+value+'）'}));activityPeople.value={...(overview.people||{}),...(me.value.display_name?{[me.value.username]:me.value.display_name}:{})};await Promise.all([load(),loadRelated()]);await requestedAction()}catch(e){toast(e.message,'error')}})
onBeforeUnmount(()=>{window.removeEventListener('beforeunload',warn);if(window.parent!==window)window.parent.postMessage({type:'workspace.dirty',dirty:false,busy:false},location.origin)})

import OptionPicker from '../../shared/components/OptionPicker.vue'
import {DialogTrigger} from '@/components/ui/dialog'

import {confirmDialog} from '../../shared/shadcnFeedback.js'

import {focusControl} from '../../shared/focusControl.js'



import {Badge,Button,Card,CardAction,CardContent,CardFooter,CardHeader,CardTitle,CardDescription,Checkbox,Dialog,DialogContent,DialogHeader,DialogTitle,DialogDescription,DialogFooter,DropdownMenu,DropdownMenuContent,DropdownMenuItem,DropdownMenuTrigger,Field,FieldDescription,FieldGroup,FieldLabel,Input,Spinner,Tabs,TabsContent,TabsList,TabsTrigger,Textarea} from '../../shared/shadcn-ui.js'
</script>
<template><PageHeader class="work-detail-header" show-back @back="backToOrigin"><template #title><h2 :title="item?.title" class="research-detail-title text-xl font-semibold tracking-tight">{{fresh?'新建工作项':item?.title}}</h2></template><template #actions><div v-if="item&&!fresh" class="flex flex-wrap items-center gap-2"><Button :aria-pressed="!!item.following" @click="toggleFollow" variant="outline" size="default" type="button" :disabled="(followingBusy)"><Spinner v-if="followingBusy"/>{{item.following?'★ 已关注':'☆ 关注'}}</Button><DropdownMenu v-if="external&&item.kind==='bug'"><DropdownMenuTrigger as-child><Button variant="outline" :disabled="busy||!canSourceWrite">状态操作</Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem @select="openAction('assignTo')" :disabled="(busy||!canSourceWrite)">指派</DropdownMenuItem><DropdownMenuItem v-if="status==='active'" @select="openAction('resolve')" :disabled="(busy||!canSourceWrite)">解决</DropdownMenuItem><DropdownMenuItem v-if="status==='resolved'" @select="openAction('close')" :disabled="(busy||!canSourceWrite)">测试关闭</DropdownMenuItem><DropdownMenuItem v-if="['resolved','closed'].includes(status)" @select="openAction('activate')" :disabled="(busy||!canSourceWrite)">重新激活</DropdownMenuItem></DropdownMenuContent></DropdownMenu><Button v-if="action!=='edit'&&(!external||item.kind==='bug')" @click="openAction('edit')" variant="outline" size="default" type="button" :disabled="(busy||(external&amp;&amp;!canSourceWrite))">编辑</Button><Button v-show="!loopState.active" @click="beginDelivery" :variant="preparation.state==='ready'?'default':'outline'" size="default" type="button" :disabled="(busy)||(starting)"><Spinner v-if="starting"/>发起交付</Button></div></template><template v-if="item&&!fresh&&detailTabs.length>1" #navigation><Tabs class="section-tabs" :model-value="String(tab)" @update:model-value="(value=>tab=value)($event)"><div class="flex min-w-0 items-center gap-2"><TabsList class="h-auto! max-w-full flex-wrap gap-y-1 [&>[data-slot=tabs-trigger]]:h-7"><TabsTrigger v-for="t in detailTabs" :value="t.id">{{t.name}}</TabsTrigger></TabsList></div><TabsContent v-for="t in detailTabs" :value="t.id" force-mount v-show="!(String(tab)!==t.id)" class="min-w-0"></TabsContent></Tabs></template></PageHeader><WorkLoopPanel :task-id="String(route.query.loop||'')" v-if="item&&!fresh" :key="item.id" :item="item" :services="services" :changes="deliverySummary?.changes||[]" :changes-loading="!deliverySummary" @edit="openDeliveryEditor" @drafts-saved="loadDeliverySummary" @updated="loadRelated();load()" @state="loopState=$event;syncDirty()"/><section v-if="item&&!fresh" v-show="tab!=='changes-preview'&&!loopState.active" class="mb-5 grid grid-cols-3 gap-5 border-y py-4" aria-label="工作项协作流程">
 <div class="min-w-0 space-y-2"><div class="flex flex-wrap items-center gap-2"><h3 class="text-sm font-medium">当前变更内容</h3><Badge variant="secondary">{{preparation.label}}</Badge><HelpTip text="内容已就绪仅表示变更准备完成；发布仍需选择环境、校验与审批。"/></div><p class="min-h-5 text-xs text-muted-foreground">{{preparation.total===null?deliveryError||'正在读取交付内容':preparation.total?deliveryOverview+' · '+preparation.ready+'/'+preparation.total+' 项就绪':'录入本次工作项的代码、SQL 或配置变更'}}</p><Button variant="outline" size="sm" @click="tab='changes-preview'" :disabled="busy">查看全部变更</Button><Button v-if="preparation.state==='error'" variant="outline" size="sm" @click="loadDeliverySummary">重试读取交付内容</Button><Button v-else @click="openDeliveryEditor" :variant="preparation.state==='ready'?'outline':'default'" size="sm" :disabled="busy||deliverySummaryLoading">{{preparation.state==='empty'?'录入交付内容':'维护交付内容'}}</Button></div>
 <div class="min-w-0 space-y-2"><h3 class="text-sm font-medium">接口与验证</h3><p class="min-h-5 text-xs text-muted-foreground">{{item.kind==='bug'?'从关联接口与回归用例核对修复结果':'查看关联接口变更，选择用例进行验证'}}</p><div class="flex flex-wrap gap-2"><Button @click="tab='api-documents'" variant="outline" size="sm">接口变更</Button><Button @click="openTesting" variant="outline" size="sm">{{item.kind==='bug'?'选择回归用例':'测试用例'}}</Button></div></div>
 <div class="min-w-0 space-y-2"><h3 class="text-sm font-medium">历史快照</h3><p class="min-h-5 text-xs text-muted-foreground">{{recordsError?'交付记录读取失败':recordsLoading&&!records.length?'正在读取交付记录':records.length?'已有 '+records.length+(recordsMore?'+':'')+' 条记录':'暂无交付记录'}}</p><Button v-if="recordsError" variant="outline" size="sm" @click="loadRecords()">重试读取交付记录</Button><Button v-else-if="records.length" variant="outline" size="sm" @click="tab='delivery'">查看交付记录</Button></div>
</section><SourceOperationReview v-if="pendingOperations.length&&!action&&tab==='overview'" :operations="pendingOperations" :source-url="item.url" :disabled="busy" @verified="operationVerified" @busy="operationBusyChanged"/><WorkDeliveryTracking v-if="item&&!fresh" v-show="tab!=='changes-preview'" :item-id="item.id" @updated="loadRecords()"/><p v-if="sourceError||sourceIdentity==='public'" class="r-muted">{{sourceError||'当前使用公共身份读取；解决、指派、评论等操作需验证本人账号。'}} <RouterLink :to="{path:'/settings',query:{return_to:route.fullPath,connection:item?.source?.replace(/^zentao:/,'')}}">验证本人来源账号并返回</RouterLink></p><div class="work-detail-layout" :class="{'is-fresh':fresh}"><Card v-if="item&&inlineAction" :aria-busy="busy" class="work-action-panel"><CardHeader v-if="!fresh"><CardTitle>{{({resolve:'解决并同步来源平台',close:'测试验证并关闭',activate:'重新激活',assignTo:'指派',edit:'编辑工作项',create:'新建工作项',comment:'发表评论','release-intent':'调整上线判定'})[action]}}</CardTitle><CardDescription v-if="external">修改将在确认后同步到来源平台。</CardDescription></CardHeader><template v-if="!operation"><CardContent class="min-w-0 space-y-5"><FieldGroup class="grid gap-5 md:grid-cols-2"><Field v-if="action==='create'"><FieldLabel as="div">类型</FieldLabel><OptionPicker v-model="form.kind" :options="[{value:'requirement',label:'需求'},{value:'bug',label:'Bug'}]" :style="{width:'100%',maxWidth:'100%'}"/></Field><Field v-if="!external&&['create','edit'].includes(action)"><FieldLabel as="div">负责人</FieldLabel><OptionPicker v-model="form.assigned_to" :options="assignees" all-label="暂不指派" :disabled="busy"/></Field><Field v-if="['create','edit'].includes(action)" class="md:col-span-2"><FieldLabel as="div">标题</FieldLabel><Input v-model="form.title" aria-label="工作项标题"/></Field><Field v-if="!external&&['create','edit'].includes(action)"><FieldLabel as="div">优先级</FieldLabel><OptionPicker v-model="form.priority" :options="[{value:'1',label:'紧急'},{value:'2',label:'高'},{value:'3',label:'中'},{value:'4',label:'低'}]" :style="{width:'100%',maxWidth:'100%'}"/></Field><Field v-if="!external&&form.kind==='bug'&&['create','edit'].includes(action)"><FieldLabel as="div">严重程度</FieldLabel><OptionPicker v-model="form.severity" :options="[{value:'1',label:'致命'},{value:'2',label:'严重'},{value:'3',label:'一般'},{value:'4',label:'提示'}]" :style="{width:'100%',maxWidth:'100%'}"/></Field><template v-if="action==='resolve'"><Field ><FieldLabel as="div">解决方式</FieldLabel><OptionPicker v-model="form.resolution" :options="resolutions" :style="{width:'100%',maxWidth:'100%'}"/></Field><Field ><FieldLabel as="div">禅道解决版本</FieldLabel><OptionPicker v-model="form.resolved_build" :options="builds"  :style="{width:'100%',maxWidth:'100%'}"/></Field><Field v-if="form.resolution==='duplicate'"><FieldLabel as="div">重复 Bug 编号</FieldLabel><Input v-model="form.duplicate_bug"/></Field></template><Field v-if="['resolve','assignTo'].includes(action)"><FieldLabel as="div">指派给</FieldLabel><OptionPicker v-model="form.assigned_to" :options="users"  :style="{width:'100%',maxWidth:'100%'}"/></Field><Field v-if="action==='activate'"><FieldLabel as="div">影响版本</FieldLabel><OptionPicker v-model="form.resolved_build" :options="builds"  :style="{width:'100%',maxWidth:'100%'}"/></Field><ReleaseIntentFields v-if="action==='resolve'" :key="action" :item="item" :model="form.metadata"  :disabled="busy"/><label v-if="action==='assignTo'"><span><Checkbox v-model="form.keep_following" :disabled="busy"/>转派后继续关注</span></label></FieldGroup><Field v-if="['create','edit'].includes(action)"><FieldLabel>{{form.kind==='bug'?'Bug 描述、复现步骤及预期/实际结果':'需求说明与验收标准'}}</FieldLabel><MarkdownEditor v-model="form.description" :format="external?'html':'markdown'" :source-url="item.url" :allow-images="!external" :disabled="busy" @uploading="uploading=$event"/></Field><Field v-if="external&&!['edit','release-intent'].includes(action)" class="min-w-0"><FieldLabel as="div">处理说明</FieldLabel><Textarea v-model="form.comment" :rows="({minRows:(3),maxRows:Math.max((3),16)}).minRows||4"/></Field><Field v-if="external&&action!=='release-intent'"><FieldLabel>附加图片</FieldLabel><div class="flex min-w-0 flex-wrap items-center gap-3"><Input type="file" aria-label="选择上传文件" class="w-full sm:max-w-sm" accept="image/png,image/jpeg,image/gif" multiple :disabled="busy||uploading" @change="e=>{for(const file of e.target.files||[])(chooseImages)(file);e.target.value=''}"/><Badge variant="secondary">{{form.attachments?.length||0}} 张待同步</Badge></div><FieldDescription>图片将上传到来源 Bug，与本次修改一起同步。</FieldDescription></Field><p v-if="actionNotice" role="status" class="r-muted">{{actionNotice}}</p></CardContent><CardFooter class="work-action-footer"><Button @click="cancel" variant="outline" size="default" type="button" :disabled="(busy||uploading)">取消</Button><Button @click="submit" variant="default" size="default" type="button" :disabled="(busy||uploading)"><Spinner v-if="busy||uploading"/>{{external&&action!=='release-intent'?(!form.expected_digest?'重新读取 Bug':'确认并同步来源平台'):'保存'}}</Button></CardFooter></template><template v-else><CardContent><SourceOperationReview :operations="[operation]" :source-url="item.url" @verified="operationVerified" @busy="operationBusyChanged"/></CardContent><CardFooter class="work-action-footer"><Button @click="operation=null;action=''" variant="outline" :disabled="busy||operationBusy">关闭处理区</Button></CardFooter></template></Card><template v-if="item&&!fresh"><Card v-show="tab==='overview'&&!inlineAction" class="work-content"><CardContent class="min-w-0"><h3 class="work-description-title">工作项说明</h3><RichDescription :content="remote?.bug?.steps||item.description" :format="external?'html':item.description_format" :source-url="item.url" :image-resolver="external?sourceImage:undefined" title="工作项说明" full compact thumbnails/><BugEvidence v-if="item.kind==='bug'" :key="item.id" :work-item-i-d="item.id"/><ActivityTimeline @comment="commentInput?.focus()" :activities="activities" :people="activityPeople" :remote="remote" :source-url="item.url" :image-resolver="sourceImage"/><CommentComposer :key="item.id" ref="commentInput" v-model="comment" v-model:attachments="commentAttachments" :busy="busy&&action!=='release-intent'" :disabled="!!action||(external&&!canSourceWrite)" @uploading="uploading=$event" @submit="sendComment"/></CardContent></Card><Card v-show="tab==='overview'||inlineAction" class="work-properties"><CardHeader><CardTitle>基本信息</CardTitle></CardHeader><CardContent class="min-w-0"><dl class="grid min-w-0 gap-4"><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">编号</dt><dd class="min-w-0 break-words">{{item.external_id||item.id}}</dd></div><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">状态</dt><dd class="min-w-0 break-words"><OptionPicker v-if="canChangeStatus" :model-value="item.status" :options="[{value:'open',label:'待处理'},{value:'active',label:'处理中'},{value:'resolved',label:item.kind==='bug'?'待回归':'已完成'},{value:'closed',label:'已关闭'}]" aria-label="工作项状态" :disabled="statusBusy||busy||!!action" @update:model-value="updateStatus"/><Badge v-else variant="secondary">{{external?issueStatus({external_status:status}):issueStatus(item)}}</Badge></dd></div><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">级别 / 优先级</dt><dd class="min-w-0 break-words">{{fieldLabel(liveFields,'severity',dictionaries)}} / {{fieldLabel(liveFields,'priority',dictionaries)}}</dd></div><div v-if="item.kind==='bug'" class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">修复方案</dt><dd class="min-w-0 break-words">{{fieldLabel(liveFields,'resolution',dictionaries)}}</dd></div><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">{{external?'指派给':'负责人'}}</dt><dd class="min-w-0 break-words">{{personLabel(remote?.bug?.assignedTo||item.assigned_to)}}</dd></div><div v-if="item.kind==='bug'" class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">解决人</dt><dd class="min-w-0 break-words">{{personLabel(remote?.bug?.resolvedBy||item.resolved_by)}}</dd></div><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">生产交付</dt><dd class="min-w-0 break-words"><Badge :variant="(item.release_required===true?'blue':'gray')==='red'?'destructive':'secondary'">{{item.release_required===true?'需上线':item.release_required===false?'无需上线':'待确认'}}</Badge><Badge v-if="item.release_mark?.marked" variant="outline" class="ml-2">已上线（人工）</Badge><p v-if="item.release_mark?.marked" class="text-xs text-muted-foreground">{{personLabel(item.release_mark.actor)}} · {{stamp(item.release_mark.at)}}</p><p v-if="item.release_reason||item.no_release_reason" class="property-reason">{{item.release_reason||item.no_release_reason}}</p></dd></div></dl></CardContent><CardFooter><Dialog :open="action==='release-intent'" @update:open="value=>{if(value)openAction('release-intent');else cancel()}"><DialogTrigger as-child><Button ref="releaseTrigger" variant="ghost" size="default" type="button" :disabled="busy||(external&amp;&amp;!canSourceWrite)">调整上线判定</Button></DialogTrigger><DialogContent v-if="item&&action==='release-intent'" @close-auto-focus="event=>{event.preventDefault();focusControl(releaseTrigger,{preventScroll:true})}" class="flex max-h-[90dvh] flex-col sm:max-w-lg" :show-close-button="!busy" @interact-outside="event=>{if(busy||dirty)event.preventDefault()}" @escape-key-down="event=>{if(busy)event.preventDefault()}"><DialogHeader><DialogTitle>调整上线判定</DialogTitle><DialogDescription class="sr-only">调整当前工作项的生产交付判定，详情与未发送评论会保留。</DialogDescription></DialogHeader><form class="flex min-h-0 flex-col gap-5" :aria-busy="busy" @submit.prevent="submit"><div class="min-h-0 overflow-auto"><ReleaseIntentFields :item="item" :model="form.metadata" expanded :disabled="busy"/></div><DialogFooter><Button variant="outline" type="button" :disabled="busy" @click="cancel">取消</Button><Button type="submit" :disabled="busy||!dirty"><Spinner v-if="busy"/>保存判定</Button></DialogFooter></form></DialogContent></Dialog></CardFooter></Card><WorkChangeOverview v-if="tab==='changes-preview'" class="work-records" :work-item-id="item.id" :changes="deliverySummary?.changes||[]" :services="services" :people="{...activityPeople,...(item.person_labels||{})}" :loading="deliverySummaryLoading" :error="deliveryError" @retry="loadDeliverySummary" @edit="openDeliveryEditor"/><WorkDeliveryEditor :focus-change-id="editorChangeID" :hide-next-steps="loopState.active" ref="editor" :show="showDeliveryEditor" :item="item" :services="services" :work-items="[item]" :can-manage="canManage" @state="editorState=$event;syncDirty()" @saved="loadDeliverySummary" @open-sync="openWorkspace('dbms','#/sync?work_item='+item.id)" @close="showDeliveryEditor=false"/><WorkItemDocumentChanges v-if="tab==='api-documents'" :work-item-id="item.id"/><div v-if="tab==='delivery'" class="work-records"><WorkDeliveryRecords :work-item-id="item.id" :items="records" :loading="recordsLoading" :error="recordsError" :more="recordsMore" @retry="loadRecords()" @more="loadRecords(true)"/></div></template></div><p v-if="busy&&!item" role="status" class="r-empty">正在读取工作项，请稍候…</p><section v-else-if="!item&&loadError" role="alert" class="r-empty"><p>{{loadError}}</p><Button @click="load" variant="outline" size="default" type="button">重试读取工作项</Button><Button @click="router.push(returnPath)" variant="ghost" size="default" type="button">返回原列表</Button></section><ResolveWorkItemDialog :show="resolving" :item="item" :read-identity="sourceIdentity" :operation="resolveOperation" @close="resolving=false;resolveOperation=null" @saved="resolved" @state="resolveState=$event;syncDirty()"/></template>

<style scoped>.delivery-overview{display:flex;align-items:center;gap:12px;flex-wrap:wrap;font-size:.75rem;color:var(--muted-foreground);margin:0 0 14px;padding:8px 12px;border:1px solid var(--border);border-radius:var(--radius);background:var(--panel)}.delivery-overview small{font-size:.75rem}.delivery-overview [role=alert]{color:var(--error)}</style>

<style scoped>
.work-detail-layout{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:20px;align-items:start;min-width:0}
.work-detail-layout.is-fresh{grid-template-columns:minmax(0,1fr)}
.work-action-panel,.work-content,.work-properties{min-width:0;align-self:start}
.work-action-panel{overflow:visible}
.work-action-footer{position:sticky;bottom:0;z-index:10;justify-content:flex-end;flex-wrap:wrap;gap:8px;border-top:1px solid var(--border);padding-top:16px;padding-bottom:16px;background:var(--card)}
.work-description-title{font-size:1.125rem;line-height:24px;font-weight:500;margin:0 0 16px}
.work-properties{position:sticky;top:16px}.work-records{grid-column:1/-1;min-width:0}
.property-reason{margin-top:8px;font-size:.875rem;color:var(--muted-foreground);overflow-wrap:anywhere}
.research-detail-title{max-width:none;white-space:normal;overflow-wrap:anywhere;line-height:1.5}
.work-content :deep(.description-body){margin:0}
.work-action-panel :deep(.markdown-editor textarea){min-height:clamp(180px,24dvh,240px);max-height:50dvh;resize:vertical}
.work-action-panel :deep(.editor-toolbar [role=group]){display:flex;flex-wrap:wrap;gap:4px}
@media(max-width:1050px){.work-detail-layout{grid-template-columns:minmax(0,1fr) 240px}}
@media(max-width:700px){.work-detail-header :deep(>div:first-child){flex-direction:column;align-items:stretch}.work-detail-header :deep(>div:first-child>div:first-child){flex-basis:auto;align-items:flex-start}.work-detail-header :deep(>div:first-child>div:last-child){justify-content:flex-end}}
@media(max-width:850px){.work-detail-layout{grid-template-columns:minmax(0,1fr)}.work-properties{position:static}.work-action-footer{position:static}}
</style>
